DROP TABLE IF EXISTS EarningsOutcome;				
CREATE TABLE EarningsOutcome (				
  InstitutionID VARCHAR(8),				
  DegreeAwardCode VARCHAR(2),				
  DegreeAwardName VARCHAR(100),				
  CIPCode VARCHAR(2),				
  Cohort VARCHAR(9),				
  YearsPostgrad INTEGER,				
  Percentile INTEGER,				
  Earnings INTEGER,				
  Graduates INTEGER,				
  Employed INTEGER,				
  PRIMARY KEY (InstitutionID, DegreeAwardCode, CIPCode, Cohort, YearsPostgrad, Percentile)				
);				
